export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = [];

  const pendingById = new Map();
  const subscriptions = [];

  function notify() {
    const snapshot = subscriptions.slice();

    for (let i = 0; i < snapshot.length; i += 1) {
      const listener = snapshot[i].listener;

      try {
        listener();
      } catch (_error) {
        // Listener errors are intentionally swallowed.
      }
    }
  }

  function replay(startState, changes) {
    let state = startState;

    for (let i = 0; i < changes.length; i += 1) {
      const update = changes[i].update;
      state = update(state);
    }

    return state;
  }

  function without(change) {
    const remaining = [];

    for (let i = 0; i < pending.length; i += 1) {
      if (pending[i] !== change) {
        remaining.push(pending[i]);
      }
    }

    return remaining;
  }

  return {
    getState() {
      return visible;
    },

    apply(id, update) {
      if (pendingById.has(id)) {
        throw new Error("A pending change with this id already exists");
      }

      const nextVisible = update(visible);
      const change = { id, update };

      pending.push(change);
      pendingById.set(id, change);
      visible = nextVisible;

      notify();
    },

    confirm(id) {
      if (!pendingById.has(id)) {
        return false;
      }

      const change = pendingById.get(id);
      const remaining = without(change);
      const update = change.update;
      const nextBase = update(base);
      const nextVisible = replay(nextBase, remaining);

      base = nextBase;
      pending = remaining;
      pendingById.delete(id);
      visible = nextVisible;

      notify();
      return true;
    },

    rollback(id) {
      if (!pendingById.has(id)) {
        return false;
      }

      const change = pendingById.get(id);
      const remaining = without(change);
      const nextVisible = replay(base, remaining);

      pending = remaining;
      pendingById.delete(id);
      visible = nextVisible;

      notify();
      return true;
    },

    subscribe(listener) {
      const subscription = { listener };
      let subscribed = true;

      subscriptions.push(subscription);

      return function unsubscribe() {
        if (!subscribed) {
          return;
        }

        subscribed = false;

        const index = subscriptions.indexOf(subscription);
        if (index !== -1) {
          subscriptions.splice(index, 1);
        }
      };
    },
  };
}
